I need some advice for reducing code bloat in a mature React project. Here's an example of a typical component:
```tsx
import { CloseIcon } from '@chakra-ui/icons';
import {
   Alert,
   Badge,
   Box,
   Flex,
   HStack,
   IconButton,
   Modal,
   ModalBody,
   ModalContent,
   ModalFooter,
   ModalHeader,
   ModalOverlay,
   Progress,
   Text,
   Tooltip,
   useClipboard,
   useDisclosure,
   useToast,
   useToken,
   VisuallyHiddenInput,
} from '@chakra-ui/react';
import { AIMessage, BaseMessage, HumanMessage } from '@langchain/core/messages';
import isEmpty from 'lodash/isEmpty';
import { GiPlainCircle } from 'react-icons/gi';
import { MdCircle, MdOutlineFullscreen } from 'react-icons/md';
import { saveAs } from 'file-saver';
import { useVoiceVisualizer, VoiceVisualizer, VoiceVisualizerRef } from 'react-voice-visualizer';
import React, { ChangeEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import ProgressModal from '../DynamicUI/ProgressModal';
import useOpenAI, { type FileObject } from '../../hooks/useOpenAI';
import useAgentStore from '../../stores/agent';
import { extractText } from '../../utils/api';
import { getMessageTimeStamp } from '../../utils/dates';
import instance from '../../utils/instance';
import { substituteParams } from '../../utils/macros';
import { isUrl } from '../../utils/urls';
import AssistantChatsDrawer from './AssistantChatsDrawer';
import AssistantFilesModal from './AssistantFilesModal';
import AssistantModalChatHistory from './AssistantModalChatHistory';
import AssistantModalInput from './AssistantModalInput';
import AssistantModalMenuButton from './AssistantModalMenuButton';
import AssistantModalModelSelectMenuButton from './AssistantModalModelSelectMenuButton';
import AssistantResourceModal from './AssistantResourceModal';
import PromptTokenCounter from './PromptTokenCounter';
import {
   createMessage,
   isImageType,
   isTextMIMEType,
   substituteParamsInCodeSamples,
} from './helpers';
import AssistantModalSettings from './AssistantSettings/AssistantModalSettings';
import orderBy from 'lodash/orderBy';
import { useAssistantContext } from './AssistantContext';

interface IAssistantModalProps {
   isAssistantModalOpen: boolean;
   onAssistantModalClose: () => void;
}

const AssistantModal: React.FC<IAssistantModalProps> = ({
   isAssistantModalOpen,
   onAssistantModalClose,
}) => {
   const inputRef = useRef<HTMLInputElement | null>(null);
   const importRef = useRef<HTMLInputElement | null>(null);
   const messagesEndRef = useRef<HTMLDivElement | null>(null);
   const [attachment, setAttachment] = useState<ArrayBuffer | FileObject | File | null>(null);
   const [attachmentType, setAttachmentType] = useState<string | null>(null);
   const [attachmentContents, setAttachmentContents] = useState<string | null>(null);
   const [promptText, setPromptText] = useState<string>('');
   const [transcribing, setTranscribing] = useState<boolean>(false);
   const [isMaximized, setIsMaximized] = useState('6xl');
   const [bgColor] = useToken('colors', ['assistant.bg']);

   const toast = useToast();
   const controls = useVoiceVisualizer();

   const {
      isOpen: isProgressModalOpen,
      onOpen: onProgressModalOpen,
      onClose: onProgressModalClose,
   } = useDisclosure();

   const {
      isOpen: isAssistantChatsDrawerOpen,
      onOpen: onAssistantChatsDrawerOpen,
      onClose: onAssistantChatsDrawerClose,
   } = useDisclosure();

   const {
      isOpen: isResourceOpen,
      onOpen: onResourceOpen,
      onClose: onResourceClosed,
   } = useDisclosure();

   const {
      isOpen: isSettingsOpen,
      onOpen: onSettingsOpen,
      onClose: onSettingsClose,
   } = useDisclosure();

   const { isOpen, onOpen, onClose } = useDisclosure();
   const {
      isReasoningModel,
      thinkTag,
      threads,
      threadId,
      selectThread,
      createThread,
      deleteThread,
      files,
      isAssistant,
      logging,
      setLogging,
      isAgent,
      setIsAgent,
      handler,
      messages,
      deleteMessage,
      updateMessages,
      isLoading,
      setIsLoading,
      clearChatHistory,
      model,
      api,
      deleteFile,
      getFileContent: downloadFile,
      mutateFiles,
      setAgentLog,
      agentLog,
      webResource,
      setWebResource,
      progress,
      setProgress,
      progressTitle,
      isProgressDeterminate,
      processWebResource,
      processLocalResource,
      enabledDocumentIds,
      setEnabledDocumentIds,
      thread,
      updateThread,
      deleteDocument,
      clearDocuments,
      response,
      useRag,
      setUseRag,
      abort,
      isLoadingDocuments,
      personaAvatar,
      username,
      useMacros,
      tokenCount,
      userIcon,
      useTranscription,
      filteredTools,
      abortProcessWebResource,
   } = useAssistantContext();
   const { uploadFile } = useOpenAI(isAssistant!);
   const { onCopy } = useClipboard(model!);

   const sortedThreads = useMemo(
      () => orderBy(threads || [], [thread => new Date(thread.createdAt).getTime()], ['desc']),
      [threads]
   );

   const {
      audioRef,
      startRecording,
      stopRecording,
      mediaRecorder,
      isAvailableRecordedAudio,
      audioSrc,
      clearCanvas,
   } = controls;

   const agentStore = useAgentStore();

   const handleApproveToolCall = useCallback(
      async (index: number) => {
         try {
            await agentStore.resolveToolCall(index, true);
         } catch (error) {
            console.error('Error approving tool call:', error);
            toast({
               title: 'Error',
               description: 'Failed to approve tool call',
               status: 'error',
               duration: 3000,
               isClosable: true,
            });
         }
      },
      [agentStore, toast]
   );

   const handleRejectToolCall = useCallback(
      async (index: number) => {
         try {
            await agentStore.resolveToolCall(index, false);
         } catch (error) {
            console.error('Error rejecting tool call:', error);
            toast({
               title: 'Error',
               description: 'Failed to reject tool call',
               status: 'error',
               duration: 3000,
               isClosable: true,
            });
         }
      },
      [agentStore, toast]
   );

   const handlePaste = async (event: ClipboardEvent) => {
      const items = event?.clipboardData?.items;
      for (let i = 0; i < items?.length!; i++) {
         if (items?.[i].kind === 'file' && items?.[i].type.includes('image')) {
            const file = items[i].getAsFile();
            if (file) {
               const reader = new FileReader();
               reader.onload = () => {
                  setAttachment(reader.result as ArrayBuffer);
                  setAttachmentType(file.type ?? 'image/*');
               };
               reader.readAsArrayBuffer(file);
               event.preventDefault(); // Prevent default paste behavior
            }
         }
      }
   };

   const handleKeyDown = useCallback(
      (event: React.KeyboardEvent) => {
         const target = event.target as HTMLElement;

         if (
            event.key === '`' &&
            (mediaRecorder as MediaRecorder)?.state !== 'recording' &&
            target.tagName !== 'INPUT' &&
            target.tagName !== 'TEXTAREA'
         ) {
            startRecording();
         }
      },
      [mediaRecorder, startRecording]
   );

   const handleKeyUp = useCallback(
      (event: React.KeyboardEvent) => {
         const target = event.target as HTMLElement;

         if (
            event.key === '`' &&
            (mediaRecorder as MediaRecorder)?.state === 'recording' &&
            target.tagName !== 'INPUT' &&
            target.tagName !== 'TEXTAREA'
         ) {
            stopRecording();
         }
      },
      [mediaRecorder, stopRecording]
   );

   useEffect(() => {
      // we add the event listener when the assistant modal is open
      // and remove it when the assistant modal is closed
      if (isAssistantModalOpen) {
         document.addEventListener('paste', handlePaste);
      } else {
         document.removeEventListener('paste', handlePaste);
      }

      return () => {
         document.removeEventListener('paste', handlePaste);
      };
   }, [isAssistantModalOpen]);

   useEffect(() => {
      if (isAssistantModalOpen) {
         setTimeout(() => {
            if (!messagesEndRef.current) {
               return;
            }
            messagesEndRef.current!.scrollIntoView({ behavior: 'smooth' });
         }, 100);
      }
   }, [isAssistantModalOpen, messages.length]);

   const handleGeneration = useCallback(async () => {
      if (isLoading || !api || !model) {
         return;
      }

      setAgentLog('');
      setIsLoading(true);

      try {
         if (isUrl(promptText)) {
            await processWebResource(promptText.trim());
            setPromptText('');
         } else {
            const messageText =
               useMacros && api !== 'openai'
                  ? substituteParamsInCodeSamples(promptText, substituteParams)
                  : promptText;

            const message = await createMessage(messageText, 'user', api!, model!, {
               user: username,
               force_avatar: `/User Avatars/${personaAvatar}`,
               attachment,
               attachmentType,
               attachmentContents,
            });
            setPromptText('');
            await handler(message);
         }
      } catch (error) {
         console.error('Error in handleGeneration:', error);
      } finally {
         setAttachment(null);
         setAttachmentContents(null);
         setAttachmentType(null);
         setIsLoading(false);
      }
   }, [
      api,
      model,
      promptText,
      useMacros,
      username,
      personaAvatar,
      attachment,
      attachmentType,
      attachmentContents,
      handler,
      processWebResource,
   ]);

   const continueGeneration = useCallback(async () => {
      if (isLoading) return; // Prevent multiple calls while already loading

      setIsLoading(true);

      try {
         toast.promise(handler(undefined, true), {
            loading: { title: 'Continuing...' },
            success: {
               title: 'Done.',
               description: 'Message generated successfully.',
               isClosable: true,
            },
            error: {
               title: 'Error generating message',
               description: 'Error generating message. Please try again.',
               isClosable: true,
            },
         });
      } catch (error) {
         console.error('Error in continueGeneration:', error);
      }
   }, [handler]);

   const transcribe = useCallback(async () => {
      if (!isEmpty(audioSrc)) {
         const { data: blob } = await instance.get(audioSrc, { responseType: 'blob' });

         const audioFile = new File([blob], 'recording.wav', {
            type: 'audio/wav',
         });

         const formData = new FormData();
         formData.append('file', audioFile);

         try {
            setTranscribing(true);
            const { data } = await instance.post('/api/v1/transcribe/', formData);
            setTranscribing(false);

            if (data.message !== '' && useTranscription) {
               setPromptText(data.message);
            }
         } catch (error: any) {
            console.error('Error processing audio file:', error);

            toast({
               title: 'Error processing audio file',
               description: error.message,
               status: 'error',
               duration: 3000,
               isClosable: true,
            });
         }
      } else {
         toast({ title: 'No audio data', status: 'warning' });
      }
   }, [audioSrc, useTranscription]);

   useEffect(() => {
      const handleTranscription = async () => {
         if (isAvailableRecordedAudio!) {
            await transcribe();
            clearCanvas();
         }
      };
      handleTranscription();
   }, [clearCanvas, isAvailableRecordedAudio, transcribe]);

   const handleRegeneration = useCallback(async () => {
      if (isLoading) {
         return;
      }

      if (!messages.some(message => message instanceof HumanMessage) || messages.length < 2) {
         toast({
            title: 'No user messages',
            description: 'Please send a message first.',
            status: 'warning',
            duration: 3000,
            isClosable: true,
         });
         return;
      }

      setIsLoading(true);

      try {
         // For regeneration, we don't pass any input message since we want to
         // regenerate the response to the existing conversation
         await handler(undefined, false, true);
         setIsLoading(false);
      } catch (error) {
         console.error('Error in handleRegeneration:', error);
         setIsLoading(false); // Make sure to reset loading state on error
      }
   }, [messages, isLoading, toast, handler]);

   const handleClearChatHistory = useCallback(async () => {
      await clearChatHistory();
   }, [clearChatHistory]);

   const handleExport = useCallback(async () => {
      const exportString = messages
         .map((message: BaseMessage) => JSON.stringify(message.toDict()))
         .join('\n');

      const exportBlob = new Blob([exportString], {
         type: 'text/plain;charset=utf-8',
      });

      saveAs(exportBlob, `Assistant - ${getMessageTimeStamp()}.jsonl`);
   }, [messages]);

   const handleImport = useCallback(
      async (event: ChangeEvent<HTMLInputElement>) => {
         const file = event.target?.files?.[0];
         if (!file) {
            return;
         }
         const fileReader = new FileReader();
         fileReader.onload = async e => {
            const fileContents = e.target?.result as string;
            const parsedFileContents: BaseMessage[] = fileContents
               .split('\n')
               .map(line => {
                  if (!line.trim()) return null;
                  const parsedLine = JSON.parse(line);
                  // Convert the JSONL format to LangChain messages
                  if (parsedLine.type === 'ai') {
                     return new AIMessage(parsedLine.data.content, {
                        name: parsedLine.data.name,
                        ...parsedLine.data.additional_kwargs,
                     });
                  } else if (parsedLine.type === 'human') {
                     return new HumanMessage(parsedLine.data.content, {
                        name: parsedLine.data.name,
                        ...parsedLine.data.additional_kwargs,
                     });
                  }
                  return null;
               })
               .filter((msg): msg is BaseMessage => msg !== null);
            await updateMessages(parsedFileContents);
         };
         fileReader.readAsText(file);
      },
      [updateMessages]
   );

   const showToast = useCallback(
      (title: string, description: string, status: 'success' | 'error') => {
         toast({
            title,
            description,
            status,
            duration: 3000,
            isClosable: true,
         });
      },
      [toast]
   );

   const processTextFile = useCallback(async (file: File, text: string) => {
      setAttachmentContents(text);
      setAttachment(file);
   }, []);

   const handleImageUpload = useCallback((file: File) => {
      const reader = new FileReader();

      // perhaps some sort of compression or resizing could be done here
      reader.onload = async () => {
         setAttachment(reader.result as ArrayBuffer);
         setProgress(100);
      };

      reader.onprogress = event => {
         if (event.lengthComputable) {
            setProgress((event.loaded / event.total) * 100);
         }
      };

      reader.onerror = event => {
         console.error('Error reading file:', event);
         setProgress(0);
         showToast('Error reading file', 'Error reading file. Please try again.', 'error');
      };

      reader.readAsArrayBuffer(file);
   }, []);

   const handleAttachment = useCallback(async () => {
      const file = inputRef.current?.files?.[0];
      if (!file) {
         return;
      }
      try {
         setAttachmentContents(null);

         if (isAssistant) {
            return await uploadFile(file, 'assistants', setProgress);
         }

         if (isImageType(file)) {
            handleImageUpload(file);
            setAttachmentType(file.type ?? 'image/*');
            showToast('File attached', `File ${file.name} has been attached.`, 'success');
         } else {
            const text = isTextMIMEType(file.type) ? await file.text() : await extractText(file);
            toast.promise(
               processTextFile(file, text),

               {
                  loading: { title: 'Attaching file...' },
                  success: {
                     title: 'File attached.',
                     description: `File ${file.name} has been attached.`,
                  },
                  error: {
                     title: 'Error attaching file',
                     description: 'Error attaching file. Please try again.',
                  },
               }
            );
            setAttachmentType(file.type);
         }
      } catch (error: any) {
         console.error('Error attaching file:', error);
         showToast('Error attaching file', error.message, 'error');
      }
   }, [isAssistant, showToast]);

   const toggleSize = useCallback(() => {
      setIsMaximized(prev => (prev === '6xl' ? 'full' : '6xl'));
   }, []);

   const handleCopyModel = useCallback(() => {
      onCopy();
      toast({
         title: 'Model copied',
         description: 'Model has been copied to clipboard.',
         status: 'success',
         duration: 1000,
         isClosable: true,
      });
   }, [onCopy, toast]);

   const visualizerRef = useRef<VoiceVisualizerRef>(null);

   return (
      <>
         <Box onKeyDown={handleKeyDown} onKeyUp={handleKeyUp}>
            <Modal
               isOpen={isAssistantModalOpen}
               onClose={onAssistantModalClose}
               size={isMaximized}
               trapFocus={!isAssistantChatsDrawerOpen}
               scrollBehavior="inside"
               blockScrollOnMount={false}
            >
               <ModalOverlay />
               <ModalContent overflow="hidden">
                  <ModalHeader>Assistant</ModalHeader>
                  <Flex position="absolute" top="0" right="0" alignItems="center">
                     <AssistantModalModelSelectMenuButton />
                     <IconButton
                        aria-label="Maximize"
                        size="md"
                        icon={<MdOutlineFullscreen />}
                        my={2}
                        mx={2}
                        variant="ghost"
                        onClick={() => toggleSize()}
                        _hover={{
                           background: 'rgba(214, 188, 250, 0.12)',
                        }}
                     />

                     <IconButton
                        aria-label="close"
                        onClick={onAssistantModalClose}
                        icon={<CloseIcon boxSize="4" />}
                        variant="ghost"
                        size="md"
                        mr="2"
                     />
                  </Flex>
                  <ModalBody backgroundColor={bgColor} overflow="hidden" p={0}>
                     <Flex
                        flexDirection="column"
                        height={isMaximized === 'full' ? '92vh' : '70vh'}
                        maxH={isMaximized === 'full' ? '88vh' : '70vh'}
                     >
                        {mediaRecorder && mediaRecorder.state === 'recording' && (
                           <Alert status="info" mb={2}>
                              <GiPlainCircle color="red" />
                              <Text ml="2">Recording...</Text>
                           </Alert>
                        )}

                        {/* Chat history */}
                        <Box flex="1" overflow="hidden" minH="0">
                           <AssistantModalChatHistory
                              isMaximized={isMaximized === 'full'}
                              agentLog={agentLog}
                              messages={messages}
                              messagesEndRef={messagesEndRef}
                              isLoading={isLoading}
                              userIcon={userIcon}
                              onApproveToolCall={handleApproveToolCall}
                              onRejectToolCall={handleRejectToolCall}
                              isReasoningModel={isReasoningModel}
                              thinkTag={thinkTag}
                           />
                        </Box>

                        <VoiceVisualizer
                           ref={visualizerRef}
                           controls={controls}
                           height="0px"
                           width="70vw"
                           isControlPanelShown={false}
                        />

                        {/* Input area */}
                        <Flex
                           p={2}
                           gap={2}
                           borderColor="gray.600"
                           bg={bgColor}
                           minH="60px"
                           w="full"
                           shrink={0}
                        >
                           <AssistantModalMenuButton
                              model={model!}
                              resource={webResource}
                              isAssistantChatsDrawerOpen={isAssistantChatsDrawerOpen}
                              onOpen={onOpen}
                              attachment={attachment}
                              setAttachment={setAttachment}
                              handleRegeneration={handleRegeneration}
                              inputRef={inputRef}
                              handleClearChatHistory={handleClearChatHistory}
                              handleExport={handleExport}
                              importRef={importRef}
                              logging={Boolean(logging)}
                              setLogging={setLogging}
                              isAgent={Boolean(isAgent)}
                              setIsAgent={setIsAgent}
                              onAssistantChatsDrawerClose={onAssistantChatsDrawerClose}
                              onAssistantChatsDrawerOpen={onAssistantChatsDrawerOpen}
                              clearDocuments={clearDocuments}
                              useRag={Boolean(useRag)}
                              setUseRag={setUseRag}
                              handleContinue={continueGeneration}
                              onResourceOpen={onResourceOpen}
                              onSettingsOpen={onSettingsOpen}
                           />

                           <Box flex={1}>
                              <AssistantModalInput
                                 abort={abort}
                                 handleGeneration={handleGeneration}
                                 isLoading={isLoading}
                                 isLoadingDocuments={isLoadingDocuments}
                                 setPromptText={setPromptText}
                                 promptText={promptText}
                              />
                           </Box>

                           <VisuallyHiddenInput
                              ref={inputRef}
                              onChange={handleAttachment}
                              type="file"
                           />

                           <VisuallyHiddenInput
                              ref={importRef}
                              onChange={handleImport}
                              type="file"
                           />
                        </Flex>
                     </Flex>
                  </ModalBody>

                  <ModalFooter>
                     <HStack w="full" spacing={4}>
                        {/* Left-aligned controls */}
                        <HStack spacing={2} flexShrink={0}>
                           <Tooltip
                              label={logging ? 'Tracing is enabled' : 'Tracing is disabled'}
                              aria-label="Tracing"
                           >
                              <IconButton
                                 aria-label="Toggle tracing"
                                 bg="transparent"
                                 _hover={{ bg: 'transparent' }}
                                 size="sm"
                                 color={logging ? 'green.500' : 'red.500'}
                                 icon={<MdCircle size="16px" />}
                                 variant="ghost"
                                 onClick={() => {
                                    console.log('Toggle logging from:', logging, 'to:', !logging);
                                    setLogging(!logging);
                                 }}
                              />
                           </Tooltip>
                           <HStack align="center" spacing={2}>
                              <Tooltip label="Click to copy model name">
                                 <Text
                                    fontSize="sm"
                                    fontWeight="medium"
                                    onClick={handleCopyModel}
                                    cursor="pointer"
                                    transition="color 0.2s"
                                 >
                                    {model}
                                 </Text>
                              </Tooltip>
                              {isAgent && (
                                 <Badge
                                    fontSize="sm"
                                    fontWeight="medium"
                                    borderRadius="sm"
                                    variant="outline"
                                 >
                                    {filteredTools?.length || 0}{' '}
                                    {filteredTools?.length === 1 ? 'tool' : 'tools'}
                                 </Badge>
                              )}
                           </HStack>
                        </HStack>

                        {/* Center-aligned progress bar */}
                        <Box flex={1} minW="100px" mx={2}>
                           {isLoadingDocuments && (
                              <HStack w="full">
                                 <Tooltip label={progressTitle} placement="top">
                                    <Text
                                       fontSize="sm"
                                       whiteSpace="nowrap"
                                       noOfLines={1}
                                       maxW="200px"
                                       title={progressTitle}
                                    >
                                       {progressTitle}
                                    </Text>
                                 </Tooltip>
                                 <Progress
                                    value={progress}
                                    isIndeterminate={!isProgressDeterminate}
                                    size="sm"
                                    flex={1}
                                    borderRadius="sm"
                                    hasStripe
                                    isAnimated
                                 />
                                 <IconButton
                                    aria-label="Cancel"
                                    icon={<CloseIcon />}
                                    size="xs"
                                    variant="ghost"
                                    onClick={abortProcessWebResource}
                                 />
                              </HStack>
                           )}
                        </Box>

                        {/* Right-aligned token counter */}
                        <HStack flexShrink={0}>
                           <PromptTokenCounter tokenCount={tokenCount} />
                        </HStack>
                     </HStack>
                  </ModalFooter>
               </ModalContent>
            </Modal>

            {isProgressModalOpen && (
               <ProgressModal
                  isOpen={isProgressModalOpen}
                  onClose={onProgressModalClose}
                  progress={progress}
                  isAnimated
                  hasStripe
               />
            )}

            {isOpen && (
               <AssistantFilesModal
                  mutateFiles={mutateFiles}
                  deleteFile={deleteFile}
                  downloadFile={downloadFile}
                  deleteDocument={deleteDocument}
                  uploadFile={uploadFile}
                  files={files?.data || []}
                  thread={thread!}
                  updateThread={updateThread}
                  isOpen={isOpen}
                  onClose={onClose}
                  isAssistant={isAssistant!} // Pass the isAssistant prop here
                  processLocalResource={processLocalResource}
                  enabledDocumentIds={enabledDocumentIds}
                  setEnabledDocumentIds={setEnabledDocumentIds}
               />
            )}

            {isResourceOpen && (
               <AssistantResourceModal
                  resource={webResource}
                  setResource={setWebResource}
                  isResourceOpen={isResourceOpen}
                  onResourceClosed={onResourceClosed}
                  processWebResource={processWebResource}
                  processLocalResource={processLocalResource}
               />
            )}

            {isSettingsOpen && (
               <AssistantModalSettings
                  isSettingsOpen={isSettingsOpen}
                  onSettingsClose={onSettingsClose}
               />
            )}
         </Box>
         {isAssistantChatsDrawerOpen && (
            <AssistantChatsDrawer
               isOpen={isAssistantChatsDrawerOpen}
               onClose={onAssistantChatsDrawerClose}
               threads={sortedThreads}
               createThread={createThread}
               selectedThreadId={threadId}
               onSelect={selectThread}
               deleteThread={deleteThread}
            />
         )}
      </>
   );
};

export default AssistantModal;
```

Could you show me what the component would look like refactored in a way that reduces it's verbosity, improves it's maintainability and then distill some general rules or guides to use going forward?

Here's a refactored version of your component focusing on reducing bloat and improving maintainability:

```tsx
// AssistantModal.tsx (refactored)
import React from 'react';
import { useAssistantModal } from './useAssistantModal';
import AssistantModalHeader from './AssistantModalHeader';
import AssistantModalBody from './AssistantModalBody';
import AssistantModalFooter from './AssistantModalFooter';
import {
  ProgressModal,
  AssistantFilesModal,
  AssistantResourceModal,
  AssistantModalSettings,
