```typescript
// frontend/src/components/KnowledgeGraphViewer.tsx
import React, { useRef, useEffect } from 'react';
import * as d3 from 'd3';

interface GraphNode {
  id: string;
  label: string;
  type: string;
}

interface GraphLink {
  source: string;
  target: string;
  label: string;
}

interface KnowledgeGraphViewerProps {
  nodes: GraphNode[];
  links: GraphLink[];
  selectedAgent?: string;
}

const KnowledgeGraphViewer: React.FC<KnowledgeGraphViewerProps> = ({ 
  nodes, links, selectedAgent 
}) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!svgRef.current) return;

    const width = 800;
    const height = 600;

    const svg = d3.select(svgRef.current)
      .attr('width', width)
      .attr('height', height);

    // Clear previous render
    svg.selectAll('*').remove();

    // Create simulation
    const simulation = d3.forceSimulation(nodes as any)
      .force('link', d3.forceLink(links).id((d: any) => d.id))
      .force('charge', d3.forceManyBody())
      .force('center', d3.forceCenter(width / 2, height / 2));

    // Draw links
    const link = svg.append('g')
      .selectAll('line')
      .data(links)
      .enter().append('line')
      .attr('stroke', '#999')
      .attr('stroke-opacity', 0.6)
      .attr('stroke-width', 2);

    // Draw nodes
    const node = svg.append('g')
      .selectAll('circle')
      .data(nodes)
      .enter().append('circle')
      .attr('r', 5)
      .attr('fill', (d: any) => {
        if (d.type === 'person') return '#ff6b6b';
        if (d.type === 'organization') return '#4ecdc4';
        if (d.type === 'concept') return '#45b7d1';
        if (d.type === 'event') return '#f9c74f';
        return '#999';
      });

    // Add labels
    const label = svg.append('g')
      .selectAll('text')
      .data(nodes)
      .enter().append('text')
      .text((d: any) => d.label)
      .attr('font-size', 12)
      .attr('dx', 10)
      .attr('dy', 4);

    // Update simulation on tick
    simulation.on('tick', () => {
      link
        .attr('x1', (d: any) => d.source.x)
        .attr('y1', (d: any) => d.source.y)
        .attr('x2', (d: any) => d.target.x)
        .attr('y2', (d: any) => d.target.y);

      node
        .attr('cx', (d: any) => d.x)
        .attr('cy', (d: any) => d.y);

      label
        .attr('x', (d: any) => d.x)
        .attr('y', (d: any) => d.y);
    });

  }, [nodes, links, selectedAgent]);

  return <svg ref={svgRef} className="knowledge-graph" />;
};

export default KnowledgeGraphViewer;
```

