### 2. Knowledge Graph Visualization with Sigma.js

```tsx
// components/KnowledgeGraph.tsx
import React, { useEffect, useRef } from 'react';
import Sigma from 'sigma';
import Graph from 'graphology';
import { useLoadGraph } from './hooks/useLoadGraph';

interface NodeAttributes {
  label: string;
  size: number;
  color: string;
  type: string;
  x?: number;
  y?: number;
}

interface EdgeAttributes {
  label?: string;
  size: number;
  color: string;
}

interface KnowledgeGraphProps {
  agentId?: string;
  topic?: string;
  compareAgentId?: string;
  width: number;
  height: number;
}

const KnowledgeGraph: React.FC<KnowledgeGraphProps> = ({
  agentId,
  topic,
  compareAgentId,
  width,
  height
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { graphData, loading, error } = useLoadGraph(agentId, topic, compareAgentId);

  useEffect(() => {
    if (!containerRef.current || !graphData) return;

    // Create graphology graph
    const graph = new Graph();

    // Add nodes
    graphData.nodes.forEach(node => {
      graph.addNode(node.id, {
        label: node.label,
        size: node.size || 5,
        color: node.color || '#666',
        type: node.type,
        x: Math.random(),
        y: Math.random()
      } as NodeAttributes);
    });

    // Add edges
    graphData.edges.forEach(edge => {
      graph.addEdge(edge.source, edge.target, {
        label: edge.label,
        size: edge.size || 1,
        color: edge.color || '#ccc'
      } as EdgeAttributes);
    });

    // Initialize Sigma.js
    const renderer = new Sigma(graph, containerRef.current, {
      renderEdgeLabels: true,
      allowInvalidContainer: false,
    });

    // Clean up
    return () => {
      renderer.kill();
    };
  }, [graphData, width, height]);

  if (loading) return <div className="graph-loading">Loading graph...</div>;
  if (error) return <div className="graph-error">Error: {error.message}</div>;

  return (
    <div 
      ref={containerRef} 
      className="knowledge-graph-container"
      style={{ width, height }}
    />
  );
};

export default KnowledgeGraph;
```

