```tsx
// hooks/useLoadGraph.ts
import { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';

interface GraphNode {
  id: string;
  label: string;
  type: string;
  size?: number;
  color?: string;
  agentId?: string;
}

interface GraphEdge {
  source: string;
  target: string;
  label?: string;
  size?: number;
  color?: string;
}

interface GraphData {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

async function fetchGraphData(
  agentId?: string, 
  topic?: string, 
  compareAgentId?: string
): Promise<GraphData> {
  let url = '/api/graph';
  const params = new URLSearchParams();

  if (agentId) params.append('agentId', agentId);
  if (topic) params.append('topic', topic);
  if (compareAgentId) params.append('compareAgentId', compareAgentId);

  if (params.toString()) url += `?${params.toString()}`;

  const response = await fetch(url);
  if (!response.ok) throw new Error('Failed to fetch graph data');
  return response.json();
}

export const useLoadGraph = (
  agentId?: string, 
  topic?: string, 
  compareAgentId?: string
) => {
  const { data, isLoading, error } = useQuery<GraphData>({
    queryKey: ['graph-data', agentId, topic, compareAgentId],
    queryFn: () => fetchGraphData(agentId, topic, compareAgentId),
    staleTime: 5 * 60 * 1000, // 5 minutes
  });

  return {
    graphData: data,
    loading: isLoading,
    error
  };
};
```

