  status?: 'active' | 'paused' | 'error';
}

const AgentNode: React.FC<NodeProps<AgentData>> = ({ data }) => {
  const statusColor = useMemo(() => {
    switch (data.status) {
      case 'active': return '#4caf50';
      case 'paused': return '#ff9800';
      case 'error': return '#f44336';
      default: return '#9e9e9e';
    }
  }, [data.status]);

  return (
    <div className="custom-node agent-node">
      <Handle type="target" position={Position.Top} />
      <div className="node-header">
        <span className="node-type-badge">Agent</span>
        <span 
          className="status-dot" 
          style={{ backgroundColor: statusColor }}
        />
      </div>
      <div className="node-content">
        <h3>{data.label}</h3>
        <p className="node-subtitle">{data.type}</p>
        <p className="node-url">{data.url}</p>
      </div>
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
};

export default AgentNode;
```

### 6. Comparison/Diff View

```tsx
// components/ComparisonView.tsx
import React, { useState } from 'react';
import KnowledgeGraph from './KnowledgeGraph';
import { useComparisonData } from '../hooks/useComparisonData';

interface ComparisonViewProps {
