        </button>
        <button 
          className={viewMode === 'diff' ? 'active' : ''}
          onClick={() => setViewMode('diff')}
        >
          Differences Only
        </button>
      </div>

      <div className={`comparison-content ${viewMode}`}>
        {viewMode === 'side-by-side' && (
          <>
            <div className="comparison-panel">
              <h3>{data?.agent1.name}</h3>
              <KnowledgeGraph 
                agentId={agent1Id} 
                topic={topic} 
                width={600} 
                height={400} 
              />
            </div>
            <div className="comparison-panel">
              <h3>{data?.agent2.name}</h3>
