                width={600} 
                height={400} 
              />
            </div>
          </>
        )}

        {viewMode === 'overlay' && (
          <div className="comparison-panel">
            <KnowledgeGraph 
              agentId={agent1Id} 
              topic={topic} 
              compareAgentId={agent2Id}
              width={800} 
