When working with async data in Zustand, there are several effective patterns to handle async fetching and store initialization. Here are the most common and recommended approaches:

## 1. Async Actions Pattern (Most Common)

This is the preferred approach where you define async actions within your store that handle the loading states:

```typescript
import { create } from 'zustand'

interface User {
  id: string
  name: string
  email: string
}

interface UserState {
  users: User[]
  loading: boolean
  error: string | null
  fetchUsers: () => Promise<void>
  initializeStore: () => Promise<void>
}

export const useUserStore = create<UserState>((set, get) => ({
  users: [],
  loading: false,
  error: null,

  fetchUsers: async () => {
    set({ loading: true, error: null })
    try {
      const response = await fetch('/api/users')
      const users = await response.json()
      set({ users, loading: false })
    } catch (error) {
      set({ error: (error as Error).message, loading: false })
    }
  },

  initializeStore: async () => {
    // You can call multiple async operations here
    await get().fetchUsers()
    // Add other initialization logic as needed
  }
}))
```

**Usage in components:**

```tsx
import { useEffect } from 'react'
import { useUserStore } from './userStore'

function UserList() {
  const { users, loading, error, fetchUsers } = useUserStore()

  useEffect(() => {
    fetchUsers()
  }, [fetchUsers])

  if (loading) return <div>Loading...</div>
  if (error) return <div>Error: {error}</div>

  return (
    <div>
      {users.map(user => (
        <div key={user.id}>{user.name}</div>
      ))}
    </div>
  )
}
```

## 2. Initialization Hook Pattern

Create a custom hook that handles the store initialization:

```typescript
// store/userStore.ts
interface UserState {
  users: User[]
  loading: boolean
  initialized: boolean
  setUsers: (users: User[]) => void
  setLoading: (loading: boolean) => void
  setInitialized: (initialized: boolean) => void
}

export const useUserStore = create<UserState>((set) => ({
  users: [],
  loading: false,
  initialized: false,
  setUsers: (users) => set({ users }),
  setLoading: (loading) => set({ loading }),
  setInitialized: (initialized) => set({ initialized }),
}))

// hooks/useInitializeStore.ts
export const useInitializeStore = () => {
  const { setUsers, setLoading, setInitialized } = useUserStore()

  useEffect(() => {
    const initialize = async () => {
      setLoading(true)
      try {
        const response = await fetch('/api/users')
        const users = await response.json()
        setUsers(users)
        setInitialized(true)
      } catch (error) {
        console.error('Failed to initialize store:', error)
      } finally {
        setLoading(false)
      }
    }

    initialize()
  }, [setUsers, setLoading, setInitialized])
}

// In your root component or App.tsx
function App() {
  useInitializeStore()
  const { initialized, loading } = useUserStore()

  if (!initialized || loading) {
    return <div>Loading application...</div>
  }

  return <YourApp />
}
```

## 3. Hydration Pattern (for SSR/Next.js)

For frameworks like Next.js, you can use a hydration pattern:

```typescript
interface UserState {
  users: User[]
  loading: boolean
  hydrate: (data: { users: User[] }) => void
  fetchUsers: () => Promise<void>
}

export const useUserStore = create<UserState>((set, get) => ({
  users: [],
  loading: false,
  hydrate: (data) => {
    set({ users: data.users })
  },
  fetchUsers: async () => {
    set({ loading: true })
    try {
      const response = await fetch('/api/users')
      const users = await response.json()
      set({ users, loading: false })
    } catch (error) {
      set({ loading: false })
      throw error
    }
  }
}))

// In your page component (Next.js example)
export async function getServerSideProps() {
  // Fetch data on server
  const response = await fetch('https://api.example.com/users')
  const users = await response.json()

  return {
    props: {
      initialUsers: users
    }
  }
}

interface PageProps {
  initialUsers: User[]
}

export default function UsersPage({ initialUsers }: PageProps) {
  const { hydrate, users } = useUserStore()

  useEffect(() => {
    hydrate({ users: initialUsers })
  }, [initialUsers, hydrate])

  return (
    // Your component JSX
  )
}
```

## 4. Advanced Pattern with Middleware

For more complex scenarios, you can use middleware:

```typescript
import { create } from 'zustand'
import { devtools } from 'zustand/middleware'

const asyncMiddleware = (config) => (set, get, api) => config({
  ...set,
  asyncSet: async (fn) => {
    const result = await fn(get())
    set(result)
  }
}, get, api)

interface UserState {
  users: User[]
  loading: boolean
  fetchUsers: () => Promise<void>
}

export const useUserStore = create<UserState>()(
  devtools(
    (set, get) => ({
      users: [],
      loading: false,
      fetchUsers: async () => {
        set({ loading: true })
        try {
          const response = await fetch('/api/users')
          const users = await response.json()
          set({ users, loading: false })
        } catch (error) {
          set({ loading: false })
        }
      }
    }),
    { name: 'UserStore' }
  )
)
```

## Best Practices Summary

1. **Use async actions** within your store rather than external functions
2. **Handle loading states** properly to provide good UX
3. **Manage errors** gracefully within your store
4. **Use the initialization hook pattern** for app-wide store initialization
5. **Consider hydration** for SSR frameworks
6. **Keep store logic focused** and composable

## Recommended Approach

For most use cases, I recommend the **Async Actions Pattern** (#1) as it's the most straightforward and keeps all the store logic contained within the store itself. The initialization is then triggered from your React components where needed.

```typescript
// Simple, effective pattern
useEffect(() => {
  store.initializeStore()
}, [])
```

This approach provides a clean separation of concerns and makes your store easy to test and reason about.

Here's an example of using LangChain and FastAPI to stream LLM responses to a front-end:

## Backend (FastAPI + LangChain)

```python
# main.py
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse
from langchain_community.llms import Ollama  # Using Ollama for local LLM
from langchain.callbacks.streaming_stdout import StreamingStdOutCallbackHandler
from langchain.callbacks.base import BaseCallbackHandler
from langchain.schema import LLMResult
import asyncio
from pydantic import BaseModel
import json

app = FastAPI()

# CORS middleware to allow frontend connections
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class StreamCallbackHandler(BaseCallbackHandler):
    """Custom callback handler for streaming tokens"""

    def __init__(self, queue):
        self.queue = queue

    def on_llm_new_token(self, token: str, **kwargs) -> None:
        """Run when new token is generated"""
        self.queue.put_nowait(token)

class ChatRequest(BaseModel):
    message: str
    model: str = "llama2"  # Default model

@app.post("/chat/stream")
async def chat_stream(request: ChatRequest):
    """Streaming chat endpoint"""

    async def generate():
        # Create a queue to collect tokens
        queue = asyncio.Queue()

        # Initialize LLM with streaming callback
        llm = Ollama(
            model=request.model,
            callbacks=[StreamCallbackHandler(queue)],
            temperature=0.7
        )

        # Run the LLM in a separate thread to avoid blocking
        async def run_llm():
            await asyncio.get_event_loop().run_in_executor(
                None, 
                lambda: llm.invoke(request.message)
            )
            await queue.put("[DONE]")  # Signal completion

        # Start the LLM generation
        asyncio.create_task(run_llm())

        # Stream tokens as they're generated
        while True:
            token = await queue.get()
            if token == "[DONE]":
                break

            # Format as SSE (Server-Sent Events)
            data = json.dumps({"token": token})
            yield f"data: {data}\n\n"

    return StreamingResponse(
        generate(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
        }
    )

# Alternative implementation using LangChain's built-in streaming
@app.post("/chat/stream-simple")
async def chat_stream_simple(request: ChatRequest):
    """Simpler streaming implementation"""

    async def generate():
        # Initialize LLM with streaming
        llm = Ollama(
            model=request.model,
            streaming=True,
            temperature=0.7
        )

        # Collect and stream tokens
        full_response = ""
        for chunk in llm.stream(request.message):
            token = chunk
            full_response += token

            data = json.dumps({
                "token": token,
                "full_response": full_response
            })
            yield f"data: {data}\n\n"

    return StreamingResponse(
        generate(),
        media_type="text/event-stream"
    )

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

## Frontend (HTML + JavaScript)

```html
<!DOCTYPE html>
