## Updated Backend for Better Streaming

Here's an improved backend that works better with axios/fetch:

```python
# main.py
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse
from langchain_community.llms import Ollama
from langchain.callbacks.base import BaseCallbackHandler
import asyncio
from pydantic import BaseModel
import json
import logging

app = FastAPI()

# CORS middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class ChatRequest(BaseModel):
    message: str
    model: str = "llama2"

class CustomStreamingCallbackHandler(BaseCallbackHandler):
    def __init__(self, queue):
        self.queue = queue

    def on_llm_new_token(self, token: str, **kwargs) -> None:
        self.queue.put_nowait(token)

async def stream_llm_response(message: str, model: str):
    """Generator function to stream LLM responses"""
    queue = asyncio.Queue()

    def run_llm():
        try:
            llm = Ollama(
                model=model,
                callbacks=[CustomStreamingCallbackHandler(queue)],
                temperature=0.7
            )
            # Run the LLM
            llm.invoke(message)
        except Exception as e:
            logger.error(f"LLM error: {e}")
            queue.put_nowait(f"\n\nError: {str(e)}")
        finally:
            queue.put_nowait(None)  # Signal completion

    # Start LLM in thread
    asyncio.get_event_loop().run_in_executor(None, run_llm)

    # Stream tokens
    while True:
        token = await queue.get()
        if token is None:
            break
        yield f"data: {json.dumps({'token': token})}\n\n"

