## Solution 2: Use a Custom Switch Wrapper Component

Create a wrapper component that manages focus and prevents scroll:

```typescript
const StableSwitch = ({ 
  path, 
  label, 
  checked, 
  onCheckedChange 
}: { 
  path: string;
  label: string;
  checked: boolean;
  onCheckedChange: (path: string, checked: boolean) => void;
}) => {
  const handleChange = useCallback(({ checked }: { checked: boolean }) => {
    // Prevent focus and potential scrolling
    onCheckedChange(path, checked);
  }, [path, onCheckedChange]);

  return (
    <Box w="full">
      <HStack justify="space-between" w="full" mb="2">
        <Text fontWeight="medium">{label}</Text>
        <Switch.Root
          checked={checked}
          onCheckedChange={handleChange}
          size="lg"
        >
          <Switch.HiddenInput />
          <Switch.Control>
            <Switch.Thumb />
          </Switch.Control>
        </Switch.Root>
      </HStack>
    </Box>
  );
};
```

