// Utility functions for common array parsing patterns
// These functions encapsulate common string splitting and cleaning operations
// used across multiple macro functions to reduce code duplication (DRY principle)
interface ParseArrayOptions {
   /** Whether to allow empty strings in the result */
   allowEmpty?: boolean;
   /** Custom separators to split on (default varies by parser type) */
   separators?: string | RegExp;
   /** Whether to remove quotes from start/end of the entire string */
   removeOuterQuotes?: boolean;
   /** Whether to handle escaped commas */
   handleEscapedCommas?: boolean;
}

/**
 * Parses a delimited string into an array with common cleaning operations
 * @param input - The string to parse
 * @param options - Configuration options for parsing
 * @returns Cleaned array of strings
 */
function parseDelimitedArray(input: string, options: ParseArrayOptions = {}): string[] {
   const {
      allowEmpty = false,
      separators = /[,:]+/,
      removeOuterQuotes = true,
      handleEscapedCommas = false,
   } = options;

   if (!input || typeof input !== 'string') {
      return [];
   }

   let processedInput = input.trim();

   // Remove outer quotes/parentheses if requested
   if (removeOuterQuotes) {
      processedInput = processedInput.replace(/^["'(]|["')]$/g, '');
   }

   // Handle escaped commas if requested
   if (handleEscapedCommas) {
      processedInput = processedInput.replace(/\\,/g, '##COMMA##');
   }

   // Split the string
   const parts = processedInput.split(separators);

   // Clean and filter the results
   const result = parts.map(part => {
      let cleaned = part.trim();
      // Restore escaped commas
      if (handleEscapedCommas) {
         cleaned = cleaned.replace(/##COMMA##/g, ',');
      }
      return cleaned;
   });

   return allowEmpty ? result : result.filter(item => item.length > 0);
}

/**
 * Parses tokens separated by colons, commonly used in mathematical macros
 * @param tokenStr - String with colon-separated tokens
 * @returns Array of non-empty trimmed tokens
 */
function parseColonTokens(tokenStr: string): string[] {
   return parseDelimitedArray(tokenStr, {
      separators: ':',
      allowEmpty: false,
   });
}

/**
 * Parses a list string that may use :: or comma separators, with support for escaped commas
 * @param listString - String with list items
 * @returns Array of cleaned list items
 */
function parseListString(listString: string): string[] {
   // Check if using :: separator first
   if (listString.includes('::')) {
      return parseDelimitedArray(listString, {
         separators: '::',
         allowEmpty: false,
      });
   }

   // Use comma separator with escaped comma support
   return parseDelimitedArray(listString, {
      separators: ',',
      allowEmpty: false,
      handleEscapedCommas: true,
   });
}

/**
 * Parses keys that may be separated by various delimiters (commas, colons, mixed)
 * @param keys - String with key identifiers
 * @returns Array of cleaned keys
 */
function parseKeyString(keys: string): string[] {
   return parseDelimitedArray(keys, {
      separators: /[,:]+/,
      allowEmpty: false,
      removeOuterQuotes: true,
   });
}

/**
 * Mathematical operation types supported by getTokenValue
 */
enum MathOperation {
   ADD = 'add',
   SUBTRACT = 'subtract',
   MULTIPLY = 'multiply',
   DIVIDE = 'divide',
}

/**
 * Configuration options for token value parsing
 */
interface TokenValueOptions {
   /** The mathematical operation being performed (affects default values and array processing) */
   operation: MathOperation;
   /** Custom default value when token cannot be parsed (overrides operation-based defaults) */
   defaultValue?: number;
   /** Custom context for error messages */
   context?: string;
}

/**
 * Reusable utility function for parsing mathematical tokens in macros.
 * Handles both individual numeric values and JSON arrays with operation-specific logic.
 *
 * @param token - The token string to parse (e.g., "123", "[1,2,3]")
 * @param options - Configuration for parsing behavior
 * @returns Parsed numeric value
 */
function getTokenValue(token: string, options: TokenValueOptions): number {
   const { operation, defaultValue, context = `${operation}Macro` } = options;

   // Get operation-specific default values
   const getDefaultValue = (): number => {
      if (defaultValue !== undefined) return defaultValue;

      switch (operation) {
         case MathOperation.ADD:
         case MathOperation.SUBTRACT:
            return 0;
         case MathOperation.MULTIPLY:
         case MathOperation.DIVIDE:
            return 1;
         default:
            return 0;
      }
   };

   const trimmed = token.trim();

   // Handle array literals
   if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
      try {
         const arr = JSON.parse(trimmed);
         if (Array.isArray(arr)) {
            if (arr.length === 0) {
               return getDefaultValue();
            }

            // Parse first element as starting value
            let result = parseFloat(arr[0]);
            if (isNaN(result)) {
               result = getDefaultValue();
            }

            // Apply operation-specific logic for remaining elements
            for (let i = 1; i < arr.length; i++) {
               const num = parseFloat(arr[i]);
               const validNum = isNaN(num) ? getDefaultValue() : num;

               switch (operation) {
                  case MathOperation.ADD:
                     result += validNum;
                     break;
                  case MathOperation.SUBTRACT:
                     result -= validNum;
                     break;
                  case MathOperation.MULTIPLY:
                     result *= validNum;
                     break;
                  case MathOperation.DIVIDE:
                     if (validNum === 0) {
                        console.error(
                           `${context}: Division by zero encountered in array: %s`,
                           arr[i]
                        );
                        continue; // Skip division by zero
                     }
                     result /= validNum;
                     break;
               }
            }
            return result;
         }
      } catch (e) {
         console.error(`${context}: Error parsing array literal: %s`, e);
      }
   }

   // Handle simple numeric values
   const num = parseFloat(trimmed);
   if (!isNaN(num)) {
      return num;
   }

   console.error(`${context}: Unable to parse token "%s" as a number.`, token);
   return getDefaultValue();
}

