export function substituteParams(
   content: string,
   _name1?: string,
   _name2?: string,
   _original?: string,
   _group?: string,
   _replaceCharacterCard: boolean = true,
   additionalMacro: Record<string, any> = {},
   sanitizer?: (value: string) => string
): string {
   if (!content) {
      return '';
   }

   if (!useSettingsStore.getState().settingsReady) {
      return content;
   }

   const environment: Environment = {};
   const name1 = _name1 ?? useSettingsStore.getState().name1;
   const name2 = _name2 ?? useSettingsStore.getState().name2;

   if (typeof _original === 'string') {
      let originalSubstituted = false;
      environment.original = () => {
         if (originalSubstituted) {
            return '';
         }
         originalSubstituted = true;
         return (_original || '').replace(/{{original}}/gi, '');
      };
   }

   const activeGroupId = useGroupStore.getState().getSelectedGroupId();
   if (activeGroupId) {
      const group = useGroupStore
         .getState()
         .getGroups()
         .find(g => g.id === activeGroupId);
      if (group && group.members) {
         environment.groupMembers = group.members.map(member => member.replace('.png', ''));
         environment.unmutedGroupMembers = group.members
            .filter(member => !group.disabled_members.includes(member))
            .map(member => member.replace('.png', ''));
         environment.mutedGroupMembers = group.members
            .filter(member => group.disabled_members.includes(member))
            .map(member => member.replace('.png', ''));
      }
   }

   if (_replaceCharacterCard) {
      const fields = getCharacterCardFields();
      environment.charPrompt = fields.system || '';
      environment.charJailbreak = fields.jailbreak || '';
      environment.description = fields.description || '';
      environment.personality = fields.personality || '';
      environment.scenario = fields.scenario || '';
      environment.persona = fields.persona || '';
      environment.mesExamples = fields.mesExamples || '';
      environment.charVersion = fields.version || '';
      environment.char_version = fields.version || '';
   }

   // Must be substituted last so that they're replaced inside {{description}}
   environment.user = _name1 ?? name1!;
   environment.char = _name2 ?? name2!;
   environment.model = getGeneratingModel();
   environment.summary = getSummary();

   if (additionalMacro && typeof additionalMacro === 'object') {
      Object.assign(environment, additionalMacro);
   }

   return evaluateMacros(content, environment, sanitizer);
}

export function substituteParamsExtended(
   content: string,
