 * @param content - The content to process
 * @param additionalMacro - Additional macros to include
 * @param sanitizer - Optional sanitizer function
 * @param options - Processing options
 * @returns The processed content or original content if processing fails
 */
export function substituteParamsExtendedSafe(
   content: string,
   additionalMacro: Record<string, any> = {},
   sanitizer?: (x: string) => string,
   options: {
      disableMacroProcessing?: boolean;
      fallbackToOriginal?: boolean;
   } = {}
): string {
   const { disableMacroProcessing = false, fallbackToOriginal = true } = options;

   if (disableMacroProcessing) {
