const isStrictNumeric = (str: string): boolean => {
   return /^-?\d+(\.\d+)?$/.test(str.trim());
};

/**
 * Adds two numbers or arrays of numbers.
 * Supports both single and multiple tokens.
 *
 * @example
 * {{add::1:2:3}} => 6
 *
 * @example
 * {{add::[1, 2, 3]}} => 6
 */
export function getAddMacro(): Macro {
   return {
      regex: /{{add::([^}]+)}}/gi,
      replace: (_match: string, tokenStr: string): string => {
         const tokens = parseColonTokens(tokenStr);

         if (tokens.length === 1) {
            const singleToken = tokens[0].trim();
            if (isStrictNumeric(singleToken)) {
               return String(parseFloat(singleToken));
            }
            if (singleToken.startsWith('[') && singleToken.endsWith(']')) {
               const result = getTokenValue(singleToken, { operation: MathOperation.ADD });
               return String(result);
            }
            console.error(
               'addMacro: Single token "%s" could not be evaluated as a number or array.',
               singleToken
            );
            return singleToken;
         }

         const total = tokens.reduce((acc: number, token: string) => {
            return acc + getTokenValue(token, { operation: MathOperation.ADD });
         }, 0);
         return String(total);
      },
   };
}

