         }

         // For multiple tokens, subtract subsequent tokens from the first one.
         const initialValue = getTokenValue(tokens[0], { operation: MathOperation.SUBTRACT });
         const total = tokens.slice(1).reduce((acc: number, token: string) => {
            return acc - getTokenValue(token, { operation: MathOperation.SUBTRACT });
