            // Array case
            if (singleToken.startsWith('[') && singleToken.endsWith(']')) {
               const result = getTokenValue(singleToken, { operation: MathOperation.DIVIDE });
               return String(result);
            }

            console.error(
               'divideMacro: Single token "%s" could not be evaluated as a number or array.',
               singleToken
            );
            return singleToken;
         }

         // Handle multiple tokens case
         const initialValue = getTokenValue(tokens[0], { operation: MathOperation.DIVIDE });
         const result = tokens.slice(1).reduce((acc: number, token: string) => {
            const divisor = getTokenValue(token, { operation: MathOperation.DIVIDE });
            if (divisor === 0) {
               console.error('divideMacro: Division by zero encountered for token "%s".', token);
               return acc;
            }
            return acc / divisor;
         }, initialValue);

         return String(result);
      },
   };
}

export function getTimeDiffMacro(): Macro {
