export function getGroupCharacterCards(groupId: number, characterId: number) {
   const groups = useGroupStore.getState().getGroups();
   const group = groups.find(
      group => groupId ?? useGroupStore.getState().getSelectedGroupId() === group.id
   );

   if (
      !group ||
      !group.generation_mode ||
      !Array.isArray(group?.members) ||
      !group.members.length
   ) {
      return null;
   }

   function customBaseChatReplace(value: string, fieldName: string, characterName: string): string {
      if (!value) {
         return '';
      }
      const name1 = useSettingsStore.getState().name1;
      value = value.replace(/<FIELDNAME>/gi, fieldName);
      return baseChatReplace(value.trim(), name1!, characterName);
   }

   function replaceAndPrepareForJoin(
      value: string,
      characterName: string,
      fieldName: string
   ): string {
      value = value.trim();

      if (!value) {
         return '';
      }

      const prefix = customBaseChatReplace(
         group?.generation_mode_join_prefix!,
         fieldName,
         characterName
      );

      const suffix = customBaseChatReplace(
         group?.generation_mode_join_suffix!,
         fieldName,
         characterName
      );

      const power_user = useSettingsStore.getState().settings?.power_user;
      const separator = power_user?.instruct.wrap ? '\n' : '';

      value = customBaseChatReplace(value, fieldName, characterName);

      return `${prefix ? prefix + separator : ''}${value}${suffix ? separator + suffix : ''}`;
   }

   const chat_metadata = useChatStore.getState().getChatMetadata();
   const characters = useCharacterStore.getState().getCharacters();
   const scenarioOverride = chat_metadata?.['scenario'];

   const descriptions: string[] = [];
   const personalities: string[] = [];
   const scenarios: string[] = [];
   const mesExamplesArray: string[] = [];

   for (const member of group.members) {
      const index = characters.findIndex(x => x.avatar === member);
      const character = characters[index];

      if (index === -1 || !character) {
         console.debug(`Skipping missing member: ${member}`);
         continue;
      }

      if (
         group.disabled_members.includes(member) &&
         characterId !== index &&
         group.generation_mode !== GroupGenerationMode.APPEND_DISABLED
      ) {
         continue;
      }

      descriptions.push(
         replaceAndPrepareForJoin(character.description ?? '', character.name, 'Description')
      );

      personalities.push(
         replaceAndPrepareForJoin(character.personality ?? '', character.name, 'Personality')
      );

      scenarios.push(
         replaceAndPrepareForJoin(character.scenario ?? '', character.name, 'Scenario')
      );

      mesExamplesArray.push(
         replaceAndPrepareForJoin(character.mes_example ?? '', character.name, 'Example Messages')
      );
   }

   const description = descriptions.filter(x => x.length).join('\n');
   const personality = personalities.filter(x => x.length).join('\n');
   const scenario = scenarioOverride?.trim() || scenarios.filter(x => x.length).join('\n');
   const mesExamples = mesExamplesArray.filter(x => x.length).join('\n');

   return { description, personality, scenario, mesExamples };
}

export function getCharacterCardFields() {
   // Get required state
   const { getCharacters, getCharacterId } = useCharacterStore.getState();
   const { settings, name1, name2 } = useSettingsStore.getState();
   const { getChatMetadata } = useChatStore.getState();

   const characters = getCharacters();
   const power_user = settings?.power_user;
   const active_group = settings?.active_group;
   const chat_metadata = getChatMetadata();
   const this_chid = getCharacterId();

   // Initialize empty result
   const result = {
      system: '',
      mesExamples: '',
      description: '',
      personality: '',
      persona: '',
      scenario: '',
      jailbreak: '',
      version: '',
   };

   // Return empty result if no valid character ID
   if (!this_chid || this_chid === -1 || !characters[this_chid]) {
      return result;
   }

   const character = characters[this_chid];

   // Process character fields
   const scenarioText = chat_metadata?.['scenario'] || character.scenario;

   result.description = baseChatReplace(character.description?.trim(), name1!, name2!);
   result.personality = baseChatReplace(character.personality?.trim(), name1!, name2!);
   result.scenario = baseChatReplace(scenarioText?.trim(), name1!, name2!);
   result.mesExamples = baseChatReplace(character.mes_example?.trim(), name1!, name2!);
   result.persona = baseChatReplace(power_user?.persona_description?.trim(), name1!, name2!);

   // Only set system/jailbreak if preferred
   if (power_user?.prefer_character_prompt) {
      result.system = baseChatReplace(character.data?.system_prompt?.trim(), name1!, name2!);
   }
   if (power_user?.prefer_character_jailbreak) {
      result.jailbreak = baseChatReplace(
         character.data?.post_history_instructions?.trim(),
         name1!,
         name2!
      );
   }

   result.version = character.data?.character_version ?? '';

   // Override with group fields if in a group
   if (active_group) {
      const groupCards = getGroupCharacterCards(active_group, Number(this_chid));
      if (groupCards) {
         result.description = groupCards.description || result.description;
         result.personality = groupCards.personality || result.personality;
         result.scenario = groupCards.scenario || result.scenario;
         result.mesExamples = groupCards.mesExamples || result.mesExamples;
      }
   }

   return result;
}

export function getChatIdHash() {
   const { getCurrentChatId } = useChatStore.getState();
   const {
      chat_metadata: chatMetadata,
      setChatMetadata,
      saveChatMetadataDebounced,
   } = useChatStore.getState();
   const cachedIdHash = chatMetadata?.['chat_id_hash'];

   // If chat_id_hash is not already set, calculate it
   if (isEmpty(cachedIdHash)) {
      // Use the main_chat if it's available, otherwise get the current chat ID
      const chatId = isEmpty(chatMetadata?.['main_chat'])
         ? getCurrentChatId()
         : chatMetadata?.['main_chat'];

      if (!chatId) {
         console.warn('Chat ID is not available');
         return 0;
      }
      const chatIdHash = getStringHash(chatId);
      const updatedChatMetadata = produce(chatMetadata, draft => {
         if (!draft) {
            return;
         }
         draft['chat_id_hash'] = String(chatIdHash);
      });

      setChatMetadata(updatedChatMetadata!);
      saveChatMetadataDebounced();

      return chatIdHash;
   }

   return cachedIdHash;
}

function getLastMessageId({
   excludeSwipeInProgress = true,
   filter = (m: Message) => true,
}: GetLastMessageIdParams = {}): number | null {
   const store = useChatStore.getState();
   const chat = store.getChat();

   for (let i = chat.length - 1; i >= 0; i--) {
      const message = chat[i];
      // If ignoring swipes and the message is being swiped, continue
      if (
         excludeSwipeInProgress &&
         message.swipes &&
         message.swipe_id !== undefined &&
         message.swipe_id >= message.swipes.length
      ) {
         continue;
      }

      // Check if no filter is provided, or if the message passes the filter
      if (!filter || filter(message)) {
         return i;
      }
   }
   return null;
}

function getLastMessage() {
