function getTimeSinceLastMessage(): string {
   const store = useChatStore.getState();
   const chat = store.getChat();

   if (Array.isArray(chat) && chat.length > 0) {
      let lastMessage: Message | undefined;
      let takeNext = false;

      for (let i = chat.length - 1; i >= 0; i--) {
         const message = chat[i];

         if (message.is_system) {
            continue;
         }

         if (message.is_user && takeNext) {
            lastMessage = message;
            break;
         }

         takeNext = true;
      }

      if (lastMessage?.send_date) {
         const lastMessageDate = timestampToDate(lastMessage.send_date);
         return formatDistanceToNow(lastMessageDate, { addSuffix: true });
      }
   }
   return 'just now';
}

function timestampToDate(timestamp: string): Date {
   return parseISO(timestamp);
}

/**
 * Replaces {{character:<character>:<attribute>}} tag in the prompt string with the specified character attribute.
 *
 * @returns {Macro} The macro object.
 *
 * @example
 * {{char::name}} - Returns the name of the current character
 *
 * @example
 * {{char::description}} - Returns the description of the current character
 * {{char::personality}} - Returns the personality of the current character
 *
 * @example
 * {{Alice::scenario}} - Returns the scenario of the character named "Alice"
 * {{Bob::first_mes}} - Returns the first message of the character named "Bob"
 *
 * @example
 * {{{{lastCharMessage}}::description}} - Uses nested macro to get description of the character who sent the last message
 *
 * @example
 * {{char}} - Returns the current character's name
 */
function getCharReplaceMacro(): Macro {
   return {
      regex: /{{(this|[^{}]+|{{[^{}]+}})::(.*?)}}/gi,
      replace: (match: string, charNameOrMacro: string, fieldName: string): string => {
         const { getCharacters, getCharacterId } = useCharacterStore.getState();
         const { name1: userName, name2: charName } = useSettingsStore.getState();
         const characters = getCharacters();
         const currentCharId = getCharacterId();

         const resolveCharName = (input: string): string => {
            if (input.startsWith('{{') && input.endsWith('}}')) {
               try {
                  return evaluateMacros(input, { user: userName!, char: charName! }) || input;
               } catch (e) {
                  console.error('Error evaluating nested character macro:', e);
                  return '';
               }
            }
            return input;
         };

         const getChar = (name: string): CharacterCard | null => {
            if (name.toLowerCase() === 'char') {
               return currentCharId !== undefined &&
                  currentCharId >= 0 &&
                  currentCharId < characters.length
                  ? characters[currentCharId]
                  : null;
            }
            return (
               characters.find(
                  c => c.name.toLowerCase() === name.toLowerCase().replace(/"/g, '').trim()
               ) || null
            );
         };

         const resolvedCharName = resolveCharName(charNameOrMacro);
         const char = getChar(resolvedCharName);

         if (!char) return '';

         if (!fieldName || fieldName.trim() === '') {
            return JSON.stringify(char).replace(/{{char}}/g, char.name);
         }

         const fieldValue = char[fieldName.trim() as keyof CharacterCard];
         if (fieldValue !== undefined) {
            const finalValue = String(fieldValue).replace(/{{char}}/g, char.name);
            return finalValue;
         }
         return '';
      },
   };
}

function getLengthMacro(env: Environment): Macro {
   return {
      regex: /{{len\s?::?([^}]+)}}/gi,
      replace: (_match: string, arrayName: string): string => {
         // Retrieve the variable from different scopes
         const variableArray =
            useVariableStore.getState().getGlobalVariables()[arrayName] ||
            useVariableStore.getState().getLocalVariables()[arrayName] ||
            env[arrayName] ||
            arrayName;

         // Determine the length based on the type of variableArray
         if (typeof variableArray === 'undefined') {
            return '0';
         }

         return getVariableLength(variableArray);
      },
   };
}

function getPickReplaceMacro(rawContent: string): Macro {
   return {
      regex: /{{pick\s?::?([^}]+)}}/gi,
      replace: (_match: string, listString: string, offset: number): string => {
         const chatIdHash = getChatIdHash();
         const rawContentHash = getStringHash(rawContent);

         // Handle JSON array case
         if (listString.startsWith('[') && listString.endsWith(']')) {
            try {
               const list = JSON.parse(listString);
               if (list.length === 0) return '';

               const combinedSeedString = `${chatIdHash}-${rawContentHash}-${offset}`;
               const finalSeed = getStringHash(combinedSeedString);
               const rng = seedrandom(String(finalSeed));
               const randomIndex = Math.floor(rng() * list.length);

               return String(list[randomIndex]);
            } catch (e) {
               console.error('Failed to parse JSON array for pick macro', e);
               return '';
            }
         }

         // Handle regular list case
         const list = parseListString(listString);

         if (list.length === 0) return '';

         const combinedSeedString = `${chatIdHash}-${rawContentHash}-${offset}`;
         const finalSeed = getStringHash(combinedSeedString);
         const rng = seedrandom(String(finalSeed));
         const randomIndex = Math.floor(rng() * list.length);

         return list[randomIndex].replace(/^"(.*)"$/, '$1');
      },
   };
}

export function baseChatReplace(value: any, name1: string, name2: string) {
   const power_user = useSettingsStore.getState().settings?.power_user;
   if (value !== undefined && value.length > 0) {
      const _ = undefined;
      value = substituteParams(value, name1, name2, _, _, false);

      if (power_user?.collapse_newlines) {
         value = collapseNewlines(value);
      }
      value = value.replace(/\r/g, '');
   }
   return value;
}

export function removeMacros(str: string): string {
