}

export function getInstructMacros(env: Environment): Macro[] {
   const power_user = useSettingsStore.getState().settings?.power_user;

   const replaceName = (
      value: string,
      {
         isUser = false,
         isSystem = false,
         isChar = false,
      }: {
         isUser?: boolean;
         isSystem?: boolean;
         isChar?: boolean;
      } = {}
   ) => {
      let replacement = value.includes('{{name}}')
         ? value.replace(
              /{{name}}/g,
              isUser
                 ? (env.user as string)
                 : isSystem
                   ? (env.system as string)
                   : isChar
                     ? (env.char as string)
                     : ''
           )
         : value;
      replacement = replacement.includes('{{char}}')
         ? replacement.replace(/{{char}}/g, env.char as string)
         : replacement;
      replacement = replacement.includes('{{user}}')
         ? replacement.replace(/{{user}}/g, env.user as string)
         : replacement;
      return replacement;
   };

   const instructMacros = [
      // Instruct template macros
      {
         key: 'instructStoryStringPrefix',
         value: power_user.instruct.story_string_prefix || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructStoryStringSuffix',
         value: power_user.instruct.story_string_suffix || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructInput|instructUserPrefix',
         value: power_user.instruct.input_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructUserSuffix',
         value: power_user.instruct.input_suffix || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructOutput|instructAssistantPrefix',
         value: power_user.instruct.output_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructSeparator|instructAssistantSuffix',
         value: power_user.instruct.output_suffix || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructSystemPrefix',
         value: power_user.instruct.system_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructSystemSuffix',
         value: power_user.instruct.system_suffix || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructFirstOutput|instructFirstAssistantPrefix',
         value:
            power_user.instruct.first_output_sequence || power_user.instruct.output_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructLastOutput|instructLastAssistantPrefix',
         value:
            power_user.instruct.last_output_sequence || power_user.instruct.output_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructStop',
         value: power_user.instruct.stop_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructUserFiller',
         value: power_user.instruct.user_alignment_message || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructSystemInstructionPrefix',
         value: power_user.instruct.last_system_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructFirstInput|instructFirstUserPrefix',
         value:
            power_user.instruct.first_input_sequence || power_user.instruct.input_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      {
         key: 'instructLastInput|instructLastUserPrefix',
         value: power_user.instruct.last_input_sequence || power_user.instruct.input_sequence || '',
         enabled: power_user.instruct.enabled,
      },
      // System prompt macros
      {
         key: 'systemPrompt',
         value:
            power_user.prefer_character_prompt && env.charPrompt
               ? env.charPrompt
               : power_user.sysprompt.content,
         enabled: power_user.sysprompt.enabled,
      },
      {
         key: 'defaultSystemPrompt|instructSystem|instructSystemPrompt',
         value: power_user.sysprompt.content,
         enabled: power_user.sysprompt.enabled,
      },
      // Context template macros
      {
         key: 'chatSeparator|exampleSeparator',
         value: power_user.context.example_separator,
         enabled: true,
      },
      {
         key: 'chatStart',
         value: power_user.context.chat_start,
         enabled: true,
      },
   ];

   const macros = [];

   for (const { key, value, enabled } of instructMacros) {
      const regex = new RegExp(`{{(${key})}}`, 'gi');
      const replace = () => (enabled ? value : '');
      macros.push({ regex, replace });
   }

   return macros as Macro[];
}

function getSummaryMacro(): Macro {
   return {
      regex: /{{summary}}/gi,
      replace: () => getSummary(),
   };
}

function getBannedWordsMacro(): Macro {
   return {
      regex: /{{banned "(.*)"}}/gi,
      replace: (_match: string, bannedWord: string): string => {
         const settings = useSettingsStore.getState().settings;
         if (settings?.main_api === 'textgenerationwebui') {
            console.log(`Found banned words in macros: ${bannedWord}`);
            CONSTANTS.textgenerationwebui_banned_in_macros.push(bannedWord);
         }
         return '';
      },
   };
}

function getRandomReplaceMacro(): Macro {
   return {
      regex: /{{random\s?::?([^}]+)}}/gi,
      replace: (_match: string, listString: string): string => {
         const list = parseListString(listString);

         if (list.length === 0) {
            return '';
         }
         const rng = seedrandom('added entropy.', { entropy: true });
         const randomIndex = Math.floor(rng() * list.length);
         return list[randomIndex];
      },
   };
}

function getChatHistoryMacro(env: Environment): Macro {
   return {
      regex: /{{chatHistory(?::(\d+))?(?:::(\d+))?(?:::(\w+))?}}/gi,
      replace: (_match: string, num1: string, num2: string, filter: string): string => {
         try {
            const numMessages = parseInt(num1 || num2 || '0', 10);
            const store = useChatStore.getState();
            const chat = store.getChat();

            let messages = numMessages ? chat.slice(-numMessages) : chat;

            if (filter) {
               switch (filter) {
                  case 'isUser':
                     messages = messages.filter(m => m.is_user);
                     break;
                  case 'isChar':
                     messages = messages.filter(m => !m.is_user && !m.is_system);
                     break;
                  case 'isSystem':
                     messages = messages.filter(m => m.is_system);
                     break;
                  default:
                     console.warn(`Unknown filter: ${filter}`);
               }
            }
            return messages.map(m => `${m.name}: ${m.mes}`).join('\n\n');
         } catch (e) {
            console.error('Error in chatHistory macro:', e);
            return '';
         }
      },
   };
}

function getGroupMacros(): Macro[] {
   const groups = useGroupStore.getState().getGroups();
   const groupId = useGroupStore.getState().getSelectedGroupId();

   if (!groupId) {
      return [];
   }

   const group = groups.find(g => g.id === groupId);
   if (!group || !group.members) {
      return [];
   }

   return [
      // Handle {{group::index}} or {{group:index}} macro
      {
         regex: /{{group(?:::|:)(\d+)}}/g,
         replace: (_match: string, indexStr: string): string => {
            const index = parseInt(indexStr, 10);
            return index < group.members.length ? group.members[index].replace('.png', '') : '';
         },
      },
      // Handle property access {{group::property::subproperty}} or {{group:property:subproperty}}
      {
         regex: /{{group(?:::|:)([^:}]+)(?:::|:)([^}]+)}}/g,
         replace: (_match: string, property: string, subproperty: string): string => {
            if (property === 'members' || property === 'member') {
               if (!isNaN(parseInt(subproperty, 10))) {
                  const index = parseInt(subproperty, 10);
                  return index < group.members.length
                     ? group.members[index].replace('.png', '')
                     : '';
               }
            } else if (property === 'chat_metadata') {
               return group.chat_metadata?.[subproperty] || '';
            }
            return '';
         },
      },
      // Legacy support for {{group::unmuted::index}} macro
      {
         regex: /{{group(?:::|:)unmuted(?:::|:)(\w+)}}/g,
         replace: (_match: string, index: string) => {
            const unmutedMembers = group.members?.filter(
               member => !group.disabled_members.includes(member)
            );
            const idx = parseInt(index, 10);
            return unmutedMembers && idx < unmutedMembers.length
               ? unmutedMembers[idx].replace('.png', '')
               : '';
         },
      },
      // Legacy support for {{group::muted::index}} macro
      {
