}

export function evaluateMacros(
   content: string,
   env: Environment,
   postProcessFn: (value: string) => string = (x: string) => x
): string {
   if (!content || typeof content !== 'string') {
      return '';
   }

   const rawContent = content;

   // Pre-environment macros
   const preEnvMacros: (Macro | Macro[])[] = [
      // Legacy non-curly macros
      {
         regex: /<USER>/gi,
         replace: () => (typeof env.user === 'function' ? env.user() : env.user || ''),
      },
      {
         regex: /<BOT>/gi,
         replace: () => (typeof env.char === 'function' ? env.char() : env.char || ''),
      },
      {
         regex: /<CHAR>/gi,
         replace: () => (typeof env.char === 'function' ? env.char() : env.char || ''),
      },
      {
         regex: /<CHARIFNOTGROUP>/gi,
         replace: () => (typeof env.group === 'function' ? env.group() : env.group || ''),
      },
      {
         regex: /<GROUP>/gi,
         replace: () => (typeof env.group === 'function' ? env.group() : env.group || ''),
      },
      getDiceRollMacro(),
      ...getInstructMacros(env),
      ...getVariableMacros(),
      { regex: /{{newline}}/gi, replace: () => '\n' },
      { regex: /\n*{{trim}}\n*/gi, replace: () => '' },
      { regex: /{{noop}}/gi, replace: () => '' },
      {
         regex: /{{input}}/gi,
         replace: () => String(document.getElementById('send_textarea')?.nodeValue ?? ''),
      },
      ...getGroupMacros(),
      getChatHistoryMacro(env),
      getSummaryMacro(),
      getCharReplaceMacro(),
      getAddMacro(),
      getSubtractMacro(),
      getMultiplyMacro(),
      getDivideMacro(),
   ];

   // Post-environment macros
   const postEnvMacros: Macro[] = [
      { regex: /{{maxPrompt}}/gi, replace: () => String(getMaxContextSize()) },
      { regex: /{{lastMessage}}/gi, replace: () => getLastMessage() },
      { regex: /{{lastMessageId}}/gi, replace: () => String(getLastMessageId() ?? '') },
      { regex: /{{lastUserMessage}}/gi, replace: () => getLastUserMessage() },
      { regex: /{{lastCharMessage}}/gi, replace: () => getLastCharMessage() },
      {
         regex: /{{firstIncludedMessageId}}/gi,
         replace: () => String(getFirstIncludedMessageId() ?? ''),
      },
      { regex: /{{lastSwipeId}}/gi, replace: () => String(getLastSwipeId() ?? '') },
      { regex: /{{currentSwipeId}}/gi, replace: () => String(getCurrentSwipeId() ?? '') },
      { regex: /{{reverse:(.+?)}}/gi, replace: (_, str) => str.split('').reverse().join('') },
      { regex: /{{time}}/gi, replace: () => format(new Date(), 'p') },
      { regex: /{{date}}/gi, replace: () => format(new Date(), 'P') },
      { regex: /{{weekday}}/gi, replace: () => format(new Date(), 'EEEE') },
      { regex: /{{isotime}}/gi, replace: () => format(new Date(), 'HH:mm') },
      { regex: /{{isodate}}/gi, replace: () => format(new Date(), 'yyyy-MM-dd') },
      {
         regex: /{{datetimeformat +([^}]*)}}/gi,
         replace: (_, formatStr) => format(new Date(), formatStr),
      },
      { regex: /{{idle_duration}}/gi, replace: () => getTimeSinceLastMessage() },
      {
         regex: /{{time_UTC([-+]\d+)}}/gi,
         replace: (_, offset) => {
            const utcOffset = parseInt(offset, 10);
            return format(new Date(new Date().setHours(new Date().getHours() + utcOffset)), 'p');
         },
      },
      { regex: /{{instructLastLine}}/gi, replace: () => instructLastLine(false, false) },
      { regex: /{{wiAfter}}/gi, replace: () => wiAfterMacro(rawContent) },
      { regex: /{{wiBefore}}/gi, replace: () => wiBeforeMacro(rawContent) },
      getTimeDiffMacro(),
      getBannedWordsMacro(),
      getRandomReplaceMacro(),
      getPickReplaceMacro(rawContent),
      getLengthMacro(env),
      getTranslateMacro(),
      getWIEntryByKeysMacro(),
      getAuthorNoteMacro(),
   ];

   // Add all registered macros to the env object
   MacrosParser.populateEnv(env);

   const nonce = uuidv4();
   const envMacros: Macro[] = [];
   // Substitute passed-in variables
   for (const varName in env) {
      if (!Object.prototype.hasOwnProperty.call(env, varName)) continue;
      if (varName === 'group') continue; // Handle group separately

      const envRegex = new RegExp(`{{${escapeRegex(varName)}}}`, 'gi');
      const envReplace = () => {
         const param = env[varName];
         return MacrosParser.sanitizeMacroValue(typeof param === 'function' ? param(nonce) : param);
      };
      envMacros.push({ regex: envRegex, replace: envReplace });
   }

   const macros = [...preEnvMacros.flat(), ...envMacros, ...postEnvMacros];

   for (const macro of macros) {
      // Stop if the content is empty or not a string
      if (!content || typeof content !== 'string') {
         break;
      }

      // Short-circuit if no curly braces are found
      if (!macro.regex.source.startsWith('<') && !content.includes('{{')) {
         break;
      }

      content = content.replace(macro.regex, (...args) =>
         postProcessFn(macro.replace(...args) || '')
      );
   }

   try {
      if (content.includes('{{')) {
         // Check for malformed handlebars syntax before compiling
         const malformedPatterns = [
            /\{\{[^}]*$/g, // Unclosed handlebars
            /\{\{[^}]*\n[^}]*$/g, // Unclosed handlebars with newlines
            /\{\{[^}]*\r[^}]*$/g, // Unclosed handlebars with carriage returns
         ];

         if (malformedPatterns.some(pattern => pattern.test(content))) {
            console.warn('Malformed Handlebars syntax detected, skipping Handlebars compilation');
            return content;
         }

         // Additional check for balanced braces
         const openBraces = (content.match(/\{\{/g) || []).length;
         const closeBraces = (content.match(/\}\}/g) || []).length;
         if (openBraces !== closeBraces) {
            console.warn('Unbalanced Handlebars braces detected, skipping Handlebars compilation');
            return content;
         }

         const template = Handlebars.compile(content, { noEscape: true, strict: false });
         content = template(env);
      }
   } catch (e) {
      console.error('Handlebars rendering failed:', e);
      // Return the content as-is instead of throwing
   }
   return content;
}

function getWIEntryByKeysMacro(): Macro {
   return {
      regex: /{{wiEntry(?:::?|\()?([^}]+)(?:\))?}}/gi,
      replace: (_match: string, keys: string) => {
         const store = useWorldStore.getState();
         // Clean up the keys string and split by common separators
         const keysArray = parseKeyString(keys);

