function getDiceRollMacro(): Macro {
   return {
      regex: /{{roll[ : ]([^}]+)}}/gi,
      replace: (_match: string, matchValue: string): string => {
         let formula: string = matchValue.trim();
         if (isDigitsOnly(formula)) {
            formula = `1d${formula}`;
         }
         const isValid: boolean = droll.validate(formula);
         if (!isValid) {
            console.debug(`Invalid roll formula: ${formula}`);
            return '';
         }
         const result: DrollResult = droll.roll(formula);
         return String(result.total);
      },
   };
}

function getTranslateMacro(): Macro {
   return {
      // Modified regex to properly capture text until the next :: or }}
      regex: /{{translate(?::)?:([^:}]+(?::[^:}]+)*?)(?::(?::)?([^}]+))?}}/gi,
      replace: (_match: string, text: string, langCode?: string): string => {
         const { addTranslation, getTranslation } = useTranslationStore.getState();

         // Remove quotes if present
         text = text.trim().replace(/^["'](.*)["']$/, '$1');

         // Generate hash from the entire text
         const hash = String(getStringHash(`${text}::${langCode}`));
         let translation = getTranslation(hash);

         if (!translation) {
            addTranslation(hash, text, langCode);
            translation = getTranslation(hash);
         }

         return translation ?? '(translating...)';
      },
   };
}

/**
 * Gets the length of a variable that could be an array, object, string, or other type
 * @param variable - The variable to measure
 * @returns The length as a string
 */
function getVariableLength(variable: any): string {
   if (Array.isArray(variable)) {
      return String(variable.length);
   }

   if (typeof variable === 'string') {
      // Attempt to parse the string as a JSON array
      try {
         const parsedArray = JSON.parse(variable);
         if (Array.isArray(parsedArray)) {
            return String(parsedArray.length);
         }
         if (typeof parsedArray === 'object' && parsedArray !== null) {
            return String(Object.keys(parsedArray).length);
         }
      } catch (e) {
         // If parsing fails, try splitting as comma-separated values first
         const commaSplit = parseDelimitedArray(variable, { separators: ',', allowEmpty: false });
         if (commaSplit.length > 1) {
            return String(commaSplit.length);
         }
         // Try splitting by words if comma split yields only one item
         const wordSplit = parseDelimitedArray(variable, { separators: /\s+/, allowEmpty: false });
         return String(wordSplit.length);
      }
      // Return the length of the string itself if all else fails
      return String(variable.length);
   }

   if (typeof variable === 'object' && variable !== null) {
      return String(Object.keys(variable).length);
   }

   if (typeof variable === 'number') {
      return String(variable);
   }

   if (typeof variable === 'boolean') {
      return variable ? '1' : '0';
   }

   // Default fallback
   return '0';
}

export class MacrosParser {
   /**
    * A map of registered macros.
    */
   private static macros: Map<string, string | MacroFunction> = new Map();

   /**
    * Registers a global macro that can be used anywhere where substitution is allowed.
    * @param {string} key Macro name (key)
    * @param {string | MacroFunction} value A string or a function that returns a string
    */
   static registerMacro(key: string, value: string | MacroFunction): void {
      if (typeof key !== 'string') {
         throw new Error('Macro key must be a string');
      }

      // Allowing surrounding whitespace would just create more confusion...
      key = key.trim();

      if (!key) {
         throw new Error('Macro key must not be empty or whitespace only');
      }

      if (key.startsWith('{{') || key.endsWith('}}')) {
         throw new Error('Macro key must not include the surrounding braces');
      }

      if (typeof value !== 'string' && typeof value !== 'function') {
         console.warn(`Macro value for "${key}" will be converted to a string`);
         value = this.sanitizeMacroValue(value);
      }

      if (this.macros.has(key)) {
         console.warn(`Macro ${key} is already registered`);
      }

      this.macros.set(key, value);
   }

   /**
    * Unregisters a global macro with the given key
    *
    * @param {string} key Macro name (key)
    */
   static unregisterMacro(key: string): void {
      if (typeof key !== 'string') {
         throw new Error('Macro key must be a string');
      }

      // Allowing surrounding whitespace would just create more confusion...
      key = key.trim();

      if (!key) {
         throw new Error('Macro key must not be empty or whitespace only');
      }

      const deleted = this.macros.delete(key);

      if (!deleted) {
         console.warn(`Macro ${key} was not registered`);
      }
   }

   /**
    * Populate the env object with macro values from the current context.
    * @param {Environment} env Env object for the current evaluation context
    * @returns {void}
    */
   static populateEnv(env: Environment): void {
      if (!env || typeof env !== 'object') {
         console.warn('Env object is not provided');
         return;
      }

      // No macros are registered
      if (this.macros.size === 0) {
         return;
      }

      for (const [key, value] of this.macros) {
         env[key] = value;
      }
   }

   /**
    * Performs a type-check on the macro value and returns a sanitized version of it.
    * @param {any} value Value returned by a macro
    * @returns {string} Sanitized value
    */
   static sanitizeMacroValue(value: any): string {
      if (typeof value === 'string') {
         return value;
      }

      if (value === null || value === undefined) {
         return '';
      }

      if (value instanceof Promise) {
         console.warn('Promises are not supported as macro values');
         return '';
      }

      if (typeof value === 'function') {
         console.warn('Functions are not supported as macro values');
         return '';
      }

      if (value instanceof Date) {
         return value.toISOString();
      }

      if (typeof value === 'object') {
         return JSON.stringify(value);
      }

      return String(value);
   }
}

/**
 * Determines if macro processing should be disabled for a document
 * @param content - The document content
 * @param metadata - Optional document metadata
 * @returns True if macro processing should be disabled
 */
export function shouldDisableMacroProcessing(content: string, metadata?: any): boolean {
   if (!content) return false;

   // Check for common file extensions that shouldn't be processed
   if (metadata?.fileName) {
      const fileName = metadata.fileName.toLowerCase();
      const skipExtensions = ['.json', '.xml', '.yaml', '.yml', '.toml', '.ini', '.cfg', '.conf'];
      if (skipExtensions.some(ext => fileName.endsWith(ext))) {
         return true;
      }
   }

   // Check for content that looks like it shouldn't be processed
   const skipPatterns = [
      /^\s*\{[\s\S]*\}\s*$/, // JSON-like content
      /^\s*<[\s\S]*>\s*$/, // XML-like content
      /^\s*#\s*[A-Z]/, // YAML-like content
   ];

   if (skipPatterns.some(pattern => pattern.test(content))) {
      return true;
   }

   // Check for malformed handlebars syntax
   const malformedPatterns = [
      /\{\{[^}]*$/g, // Unclosed handlebars
      /\{\{[^}]*\n[^}]*$/g, // Unclosed handlebars with newlines
   ];

   if (malformedPatterns.some(pattern => pattern.test(content))) {
      return true;
   }

   return false;
}

