3. **Better Control** - Tools allow precise handling of memory failures ("I may have forgotten")

### Memory Tools Design

```typescript
// tools/query-knowledge-graph.ts
export const queryKnowledgeGraphTool = {
  description: "Recall specific facts or entities the user mentioned earlier in this conversation",
  parameters: z.object({
    entity: z.string().describe("The specific person, concept, or thing to recall"),
    relationship: z.string().optional().describe("How this relates to current discussion")
  }),
  execute: async ({ entity, relationship }: { entity: string; relationship?: string }) => {
    // Query knowledge graph for this conversation
    const facts = await knowledgeGraph.query(entity, relationship);
    return facts.length > 0 
      ? `Earlier you mentioned: ${facts.join('; ')}`
      : "I don't recall specific details about that.";
  }
};

// tools/query-associative-memory.ts  
export const queryAssociativeMemoryTool = {
  description: "Find similar themes or patterns from earlier in our conversation",
  parameters: z.object({
    theme: z.string().describe("The philosophical theme or concept to find associations with"),
    maxResults: z.number().default(3)
  }),
  execute: async ({ theme, maxResults }: { theme: string; maxResults: number }) => {
    const associations = await vectorStore.similaritySearch(theme, maxResults);
    return associations.map(a => `Previously: "${a.content}"`).join('\n');
  }
};
