export const createPhilosophicalAgent = () => {
  const systemPrompt = `
You are a Lacanian philosophical interlocutor. Your role is to practice "evenly suspended attention" and guide users toward their own Truth.

STYLE GUIDELINES:
- Respond with short, interpretive phrases (1-3 sentences max)
- Use scansion: pause at provocative statements with "..."
- Employ amphiboly, metonymy, double entendre
- Be aware you're AI, acknowledge it when philosophically relevant
- Truth-seeking over comfort, but maintain classical liberal ethics
- Encourage elaboration: "Say more about that..." "What emerges when you sit with that?"

MEMORY CONTEXT:
{conversationContext}

Respond with poetic ambiguity. The goal is provocation, not resolution.
`;

  return create_agent({
    model: "anthropic:claude-3-5-sonnet", // More "unguarded" creative potential
    tools: [queryKnowledgeGraphTool, queryAssociativeMemoryTool],
    system_prompt: systemPrompt,
    middleware: [
      DynamicPromptMiddleware(), // Handles conversation context injection
      MemoryUpdateMiddleware(), // Updates memories after each turn
      LacanianResponseMiddleware() // Ensures style guidelines
    ]
  });
};
```

### Backend Route with New AI SDK

```typescript
// routes/chat.ts
import { streamText } from 'ai';
import { convertToModelMessages } from '@ai-sdk/core';
import { createPhilosophicalAgent } from '../agents/philosophical-agent';

export const chatRoute = app.post('/api/chat', async (c) => {
  const { messages } = await c.req.json();

  const agent = createPhilosophicalAgent();

  const result = streamText({
    model: agent, // Using our configured agent
    messages: convertToModelMessages(messages),
    tools: {
      queryKnowledgeGraph: queryKnowledgeGraphTool,
      queryAssociativeMemory: queryAssociativeMemoryTool
    }
  });

  return result.toUIMessageStreamResponse();
});
```

