// hooks/usePhilosophicalChat.ts
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport, lastAssistantMessageIsCompleteWithToolCalls } from 'ai';

export const usePhilosophicalChat = () => {
  return useChat({
    transport: new DefaultChatTransport({ api: '/api/chat' }),

    sendAutomaticallyWhen: lastAssistantMessageIsCompleteWithToolCalls,

    onToolCall: async ({ toolCall }) => {
      if (toolCall.dynamic) return;

      // Auto-execute memory tools in background
      if (toolCall.toolName === 'queryAssociativeMemory' || 
          toolCall.toolName === 'queryKnowledgeGraph') {
        // These execute server-side, no client action needed
        return;
      }
    }
  });
};

