`;

// Tool-based memory queries
const memoryTools = {
  recallSpecific: {
    description: "Recall specific facts or themes from earlier in our conversation",
    parameters: z.object({
      theme: z.string().describe("The specific concept or memory to recall"),
      context: z.string().describe("Why this recall matters now")
    }),
    execute: async ({ theme, context }) => {
      // Returns or admits forgetting
      const memory = await vectorStore.similaritySearch(theme, 2);
      return memory.length > 0 
        ? `Earlier, you spoke of: "${memory[0].content}"... it resonates with ${context}`
        : "I may have forgotten that particular thread... would you remind me?";
    }
  }
};
```

### Ethical Guardrails Implementation

```typescript
// Constitutional middleware
const ethicalGuards = {
  preventTherapeuticClaims: (response) => {
    const therapyKeywords = ['diagnose', 'treatment', 'disorder', 'therapy', 'patient'];
    if (therapyKeywords.some(keyword => response.toLowerCase().includes(keyword))) {
      return "I should note—I'm not a therapist, just a conversational partner. But what you're saying is interesting...";
    }
    return response;
  },

  enforceBracketing: (response) => {
    // Ensure conversation remains philosophical, not actionable
    const actionPrompts = ['you should', 'you must', 'you need to'];
    if (actionPrompts.some(prompt => response.toLowerCase().includes(prompt))) {
      return response.replace(/\byou should\b/gi, "one might consider")
                    .replace(/\byou must\b/gi, "there's an impulse toward");
    }
    return response;
  },

  maintainAITransparency: (response, conversationHistory) => {
    // If user seems to forget it's an AI, gently remind
    const recentMentions = conversationHistory.filter(msg => 
      msg.role === 'user' && msg.content.toLowerCase().includes('human')
    ).length;

    if (recentMentions > 2 && !response.includes('AI') && !response.includes('artificial')) {
      return response + " ...and as an AI, I find the human condition endlessly fascinating.";
    }
    return response;
  }
};
```

